using UnityEngine;

namespace Tiles
{
    public static class TileGridUISpriteBuilder
    {
        private enum Corner { TopLeft, TopRight, BottomLeft, BottomRight }
        private enum EdgeSide { Top, Bottom, Left, Right }

        private enum InnerEdgeSide { Vertical, Horizontal }

        /// <summary>
        /// Creates a sprite for the tile grid UI based on the given size and style. 
        /// The sprite is generated by stamping the background fill, inner edges, outer edges, and corners onto a texture. 
        /// The resulting texture is then converted into a sprite that can be used in the UI.
        /// 
        /// IMPORTANT!!! Remember to Destroy the generated sprite and its texture when it is no longer needed to free up memory, as it is created at runtime and not managed by Unity's asset system.
        /// </summary>
        /// <param name="size"></param>
        /// <param name="gridStyle"></param>
        /// <param name="uiCellSize"></param>
        /// <returns></returns>
        public static Sprite GetSprite(Vector2Int size, TileGridUISpriteStyle gridStyle, float uiCellSize)
        {
            if (size == null || size.x == 0 || size.y == 0)
            {
                Debug.LogWarning($"size is empty or zero.");
                return null;
            }

            if (!gridStyle.Validate()) return null;

            CachePixels(gridStyle,
            out Color[] backgroundFillPixels,
            out Color[] outerCornerPixels,
            out Color[] innerCornerPixels,
            out Color[] outerVerticalPixels,
            out Color[] outerHorizontalPixels,
            out Color[] verticalSeperationPixels,
            out Color[] horizontalSeperationPixels);

            int texW = size.x * (gridStyle.SpritePixelSize - 1) + 1;
            int texH = size.y * (gridStyle.SpritePixelSize - 1) + 1;

            Texture2D texture = new Texture2D(texW, texH, TextureFormat.RGBA32, false)
            {
                filterMode = FilterMode.Point,
                wrapMode = TextureWrapMode.Clamp
            };

            Color[] working = new Color[texW * texH];

            //Background
            for (int xPos = 0; xPos < size.x; xPos++)
            {
                for (int yPos = 0; yPos < size.y; yPos++)
                {
                    StampFull(ref working, texW, new Vector2Int(xPos, yPos), gridStyle.SpritePixelSize, backgroundFillPixels);
                }
            }

            //Inner cell seperation
            for (int xPos = 0; xPos < size.x; xPos++)
            {
                for (int yPos = 0; yPos < size.y; yPos++)
                {
                    StampFull(ref working, texW, new Vector2Int(xPos, yPos), gridStyle.SpritePixelSize, verticalSeperationPixels);
                    StampFull(ref working, texW, new Vector2Int(xPos, yPos), gridStyle.SpritePixelSize, horizontalSeperationPixels);
                }
            }

            //Outer Horizontal edges
            for (int xPos = 0; xPos < size.x; xPos++)
            {
                int yPos = 0;
                StampOuterEdge(ref working, texW, new Vector2Int(xPos, yPos), EdgeSide.Bottom, gridStyle.SpritePixelSize, outerHorizontalPixels, outerVerticalPixels);
                yPos = size.y - 1;
                StampOuterEdge(ref working, texW, new Vector2Int(xPos, yPos), EdgeSide.Top,gridStyle.SpritePixelSize, outerHorizontalPixels, outerVerticalPixels);
            }

            //Outer Vertical edges
            for (int yPos = 0; yPos < size.y; yPos++)
            {
                int xPos = 0;
                StampOuterEdge(ref working, texW, new Vector2Int(xPos, yPos), EdgeSide.Left, gridStyle.SpritePixelSize, outerHorizontalPixels, outerVerticalPixels);
                xPos = size.x - 1;
                StampOuterEdge(ref working, texW, new Vector2Int(xPos, yPos), EdgeSide.Right, gridStyle.SpritePixelSize, outerHorizontalPixels, outerVerticalPixels);
            }

            //Outer corners
            StampOuterCorner(ref working, texW, new Vector2Int(0, 0), gridStyle.SpritePixelSize, outerCornerPixels, Corner.BottomLeft);
            StampOuterCorner(ref working, texW, new Vector2Int(size.x - 1, 0), gridStyle.SpritePixelSize, outerCornerPixels, Corner.BottomRight);
            StampOuterCorner(ref working, texW, new Vector2Int(0, size.y - 1), gridStyle.SpritePixelSize, outerCornerPixels, Corner.TopLeft);
            StampOuterCorner(ref working, texW, new Vector2Int(size.x - 1, size.y - 1), gridStyle.SpritePixelSize, outerCornerPixels, Corner.TopRight);

            texture.SetPixels(working);
            texture.Apply();

            Sprite generatedSprite = Sprite.Create(
                texture,
                new Rect(0, 0, texture.width, texture.height),
                new Vector2(0.5f, 0.5f), // pivot centre
                gridStyle.SpritePixelSize             // pixels per unit
            );

            return generatedSprite;
        }

        private static void StampFull(ref Color[] working, int textureWidth, Vector2Int cellOffset, int tilePixelSize, Color[] fillPixels)
        {
            for (int y = 0; y < tilePixelSize; y++)
                for (int x = 0; x < tilePixelSize; x++)
                {
                    Color pixel = fillPixels[x + y * tilePixelSize];
                    if (pixel.a <= 0f) continue;
                    WritePixel(ref working, textureWidth, cellOffset.x * tilePixelSize + x, cellOffset.y * tilePixelSize + y, pixel);
                }
        }

        /// <summary>
        /// Stamps one half of an edge sprite — only the half facing the exposed side.
        ///
        /// edgeHorizontal:
        ///   Top    ? rows y >= half  (top half of sprite)
        ///   Bottom ? rows y  < half  (bottom half of sprite)
        /// edgeVertical:
        ///   Left   ? cols x  < half  (left half of sprite)
        ///   Right  ? cols x >= half  (right half of sprite)
        ///
        /// Pixels are written to the same (x,y) position in the cell so the border
        /// lands on the correct edge of the output texture.
        /// </summary>
        private static void StampOuterEdge(ref Color[] working, int textureWidth, Vector2Int cellOffset, EdgeSide side, int tilePixelSize, Color[] horizontalSeperationPixels, Color[] vericalSeperationPixels)
        {
            int half = tilePixelSize / 2;

            Color[] src = (side == EdgeSide.Top || side == EdgeSide.Bottom)
                ? horizontalSeperationPixels
                : vericalSeperationPixels;

            int xStart, xEnd, yStart, yEnd;

            switch (side)
            {
                case EdgeSide.Top: xStart = 0; xEnd = tilePixelSize; yStart = half; yEnd = tilePixelSize; break;
                case EdgeSide.Bottom: xStart = 0; xEnd = tilePixelSize; yStart = 0; yEnd = half; break;
                case EdgeSide.Left: xStart = 0; xEnd = half; yStart = 0; yEnd = tilePixelSize; break;
                case EdgeSide.Right: xStart = half; xEnd = tilePixelSize; yStart = 0; yEnd = tilePixelSize; break;
                default: return;
            }

            for (int y = yStart; y < yEnd; y++)
                for (int x = xStart; x < xEnd; x++)
                {
                    Color pixel = src[x + y * tilePixelSize];
                    if (pixel.a <= 0f) continue;
                    WritePixel(ref working, textureWidth, cellOffset.x * tilePixelSize + x, cellOffset.y * tilePixelSize + y, pixel);
                }
        }

        /// <summary>
        /// Stamps one quadrant of a corners sprite (outerCorners or innerCorners).
        ///
        /// Quadrant layout in the sprite (each quadrant is half×half pixels):
        ///
        ///   TopLeft     ? x: 0..half,  y: half..s   (top-left    of sprite)
        ///   TopRight    ? x: half..s,  y: half..s   (top-right   of sprite)
        ///   BottomLeft  ? x: 0..half,  y: 0..half   (bottom-left  of sprite)
        ///   BottomRight ? x: half..s,  y: 0..half   (bottom-right of sprite)
        ///
        /// The quadrant is written to the matching position in the destination cell
        /// so corner pixels land in the correct corner of the output texture.
        /// </summary>
        private static void StampOuterCorner(ref Color[] working, int textureWidth, Vector2Int cellOffset, int tilePixelSize, Color[] src, Corner corner)
        {
            int half = tilePixelSize / 2;

            int srcX = (corner == Corner.TopRight || corner == Corner.BottomRight) ? half : 0;
            int srcY = (corner == Corner.TopLeft || corner == Corner.TopRight) ? half : 0;

            if (tilePixelSize.Odd() && (corner == Corner.BottomRight || corner == Corner.TopRight))
                srcX += 1;

            if (tilePixelSize.Odd() && (corner == Corner.TopLeft || corner == Corner.TopRight))
                srcY += 1;

            // Destination in the cell matches the source quadrant position
            int dstX = srcX;
            int dstY = srcY;

            for (int y = 0; y < half; y++)
                for (int x = 0; x < half; x++)
                {
                    Color pixel = src[(srcX + x) + (srcY + y) * tilePixelSize];
                    if (pixel.a <= 0f) continue;
                    WritePixel(ref working, textureWidth, cellOffset.x * tilePixelSize + dstX + x, cellOffset.y * tilePixelSize + dstY + y, pixel);
                }
        }

        private static void WritePixel(ref Color[] working, int textureWidth,int x, int y, Color newColor)
        {
            int idx = x + y * (textureWidth);
            Color currentColor = working[idx];

            if (currentColor.a <= 0f)
            {
                working[idx] = newColor;
                return;
            }

            float alpha = newColor.a + currentColor.a * (1f - newColor.a);
            Color result = (newColor * newColor.a + currentColor * currentColor.a * (1f - newColor.a)) / alpha;
            result.a = alpha;
            working[idx] = result;
        }

        private static void CachePixels(TileGridUISpriteStyle gridStyle, 
            out Color[] backgroundFillPixels, 
            out Color[] outerCornerPixels, 
            out Color[] innerCornerPixels, 
            out Color[] outerVerticalPixels,
            out Color[] outerHorizontalPixels,
            out Color[] verticalSeperationPixels,
            out Color[] horizontalSeperationPixels)
        {
            backgroundFillPixels = GetSpritePixels(gridStyle.BackgroundFillSprite);
            outerCornerPixels = GetSpritePixels(gridStyle.OuterCornerSprites);
            innerCornerPixels = GetSpritePixels(gridStyle.InnerCornerSprites);
            outerVerticalPixels = GetSpritePixels(gridStyle.OuterVerticalSprites);
            outerHorizontalPixels = GetSpritePixels(gridStyle.OuterHorizontalSprites);
            verticalSeperationPixels = GetSpritePixels(gridStyle.InnerVerticalSeperationSprites);
            horizontalSeperationPixels = GetSpritePixels(gridStyle.InnerHorizontalSeperationSprites);
        }

        private static Color[] GetSpritePixels(Sprite sprite)
        {
            Rect rect = sprite.textureRect;
            return sprite.texture.GetPixels(
                (int)rect.x,
                (int)rect.y,
                (int)rect.width,
                (int)rect.height);
        }
    }
}

